def load(p):return json.loads(p.read_text())
def dump(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')
def canon(v):return json.dumps(v,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def seal(v):
 x={k:value for k,value in v.items() if k!='content_hash'}
 x.setdefault('scope_id','protocol-v14.7');x.setdefault('scope_hash',hashlib.sha256(b'protocol-v14.7').hexdigest());x.setdefault('created_at','2026-09-12T00:00:00Z')
