def failure_cell(condition,subject):
 structural={'SCHEMA','REFERENCE','SNAPSHOT'};semantic={'EVIDENCE','POLICY','AUTHORITY','CREDENTIAL','SCOPE','ARTIFACT','CERTIFICATE','ENVIRONMENT','EVALUATION'}
 if condition in {'MALFORMED','INVALID','CONTRADICTORY'}:result='INVALID'
 elif condition=='MISSING':result='INVALID'
 elif condition=='UNAVAILABLE':result='BLOCKED'
 elif condition=='BLOCKED':result='BLOCKED'
 elif condition=='UNKNOWN':result='INVALID' if subject in structural else 'UNKNOWN'
 elif condition=='STALE':result='UNKNOWN' if subject in {'EVIDENCE','CREDENTIAL','SNAPSHOT','CERTIFICATE','ENVIRONMENT','EVALUATION','AUTHORITY','POLICY'} else 'INVALID'
 elif condition=='EXPIRED':
  if subject=='EVIDENCE':result='UNKNOWN'
  elif subject in {'POLICY','AUTHORITY','CREDENTIAL','CERTIFICATE','ENVIRONMENT','EVALUATION'}:result='FALSE'
  else:result='INVALID'
 elif condition=='REVOKED':result='FALSE' if subject in {'POLICY','AUTHORITY','CREDENTIAL','CERTIFICATE'} else 'INVALID'
 elif condition=='FALSE':result='FALSE' if subject in semantic else 'INVALID'
 else:raise ValueError(condition)
 elig={'INVALID':'NO_AUTHORITATIVE_RESULT','FALSE':'INELIGIBLE','BLOCKED':'BLOCKED','UNKNOWN':'UNKNOWN'}[result]
 authorization={'INVALID':'INVALID','FALSE':'REFUSED','BLOCKED':'BLOCKED','UNKNOWN':'UNKNOWN'}[result]
 continuation='NO' if result=='INVALID' else 'AGGREGATION_ONLY'
 retry=condition in {'MISSING','STALE','UNAVAILABLE','UNKNOWN','BLOCKED'}
 reason=f'{condition}_{subject}_REQUIRED_INPUT_MAPS_TO_{result}'
 return result,elig,authorization,continuation,retry,reason

